arguments.content:
/* === Reset & Base === */
*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

:root {
  --bg: #ffffff;
  --bg-alt: #f5f5f7;
  --text: #1d1d1f;
  --text-secondary: #6e6e73;
  --link: #0066cc;
  --link-hover: #004499;
  --border: #d2d2d7;
  --shadow: 0 2px 12px rgba(0,0,0,0.08);
  --radius: 18px;
  --radius-sm: 12px;
  --max-width: 1200px;
  --font-stack: -apple-system, BlinkMacSystemFont, 'SF Pro Display', 'SF Pro Text', 'Helvetica Neue', Arial, sans-serif;
}

html { scroll-behavior: smooth; }

body {
  font-family: var(--font-stack);
  color: var(--text);
  background: var(--bg);
  line-height: 1.47059;
  font-weight: 400;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

a { color: var(--link); text-decoration: none; }
a:hover { color: var(--link-hover); text-decoration: underline; }

img { max-width: 100%; display: block; }
button { cursor: pointer; font-family: inherit; border: none; background: none; color: inherit; }

/* === Navbar === */
.navbar {
  position: sticky; top: 0; z-index: 1000;
  background: rgba(255,255,255,0.92);
  backdrop-filter: saturate(180%) blur(20px);
  -webkit-backdrop-filter: saturate(180%) blur(20px);
  border-bottom: 1px solid rgba(0,0,0,0.08);
}

.navbar-inner {
  max-width: var(--max-width);
  margin: 0 auto;
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 0 24px;
  height: 52px;
}

.nav-brand {
  font-size: 21px;
  font-weight: 600;
  color: var(--text);
  text-decoration: none;
  letter-spacing: -0.01em;
}
.nav-brand:hover { text-decoration: none; color: var(--text); }

.nav-links {
  display: flex;
  align-items: center;
  gap: 28px;
  list-style: none;
}

.nav-links a {
  font-size: 13px;
  font-weight: 400;
  color: var(--text);
  letter-spacing: -0.01em;
  transition: color 0.15s;
}
.nav-links a:hover { color: var(--link); text-decoration: none; }

.nav-actions { display: flex; align-items: center; gap: 16px; }
.nav-actions a { font-size: 13px; color: var(--text); }
.nav-actions a:hover { color: var(--link); text-decoration: none; }

/* Mobile nav */
.hamburger { display: none; flex-direction: column; gap: 5px; padding: 8px; }
.hamburger span { width: 18px; height: 2px; background: var(--text); border-radius: 2px; transition: 0.2s; }

@media (max-width: 833px) {
  .nav-links { display: none; }
  .nav-actions .nav-hide-mobile { display: none; }
  .hamburger { display: flex; }
}

/* === Sections === */
.section {
  padding: 80px 24px;
}

.section-alt {
  background: var(--bg-alt);
}

.section-header {
  text-align: center;
  margin-bottom: 48px;
}

.section-title {
  font-size: 48px;
  font-weight: 600;
  letter-spacing: -0.015em;
  line-height: 1.08349;
  color: var(--text);
}

.section-subtitle {
  font-size: 21px;
  font-weight: 400;
  color: var(--text-secondary);
  margin-top: 8px;
  letter-spacing: 0.011em;
  line-height: 1.381;
}

@media (max-width: 734px) {
  .section { padding: 48px 16px; }
  .section-title { font-size: 32px; }
  .section-subtitle { font-size: 17px; }
}

/* === Ribbon Banner === */
.ribbon-banner {
  background: var(--bg-alt);
  text-align: center;
  padding: 12px 24px;
  font-size: 14px;
  color: var(--text);
  line-height: 1.42859;
}
.ribbon-banner a {
  color: var(--link);
  font-weight: 400;
  white-space: nowrap;
}
.ribbon-banner a:hover { text-decoration: underline; }

/* === Hero === */
.hero {
  text-align: center;
  padding: 60px 24px 80px;
}

.hero-title {
  font-size: 56px;
  font-weight: 600;
  letter-spacing: -0.015em;
  line-height: 1.07143;
}

.hero-subtitle {
  font-size: 24px;
  font-weight: 400;
  color: var(--text-secondary);
  margin-top: 12px;
  letter-spacing: 0.011em;
}

.hero-ctas {
  display: flex;
  justify-content: center;
  gap: 16px;
  margin-top: 24px;
  flex-wrap: wrap;
}

@media (max-width: 734px) {
  .hero-title { font-size: 36px; }
  .hero-subtitle { font-size: 17px; }
}

/* === Buttons === */
.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  padding: 12px 24px;
  border-radius: 980px;
  font-size: 17px;
  font-weight: 400;
  letter-spacing: -0.022em;
  transition: all 0.2s;
  min-height: 44px;
}

.btn-primary {
  background: var(--link);
  color: #fff;
}
.btn-primary:hover { background: var(--link-hover); color: #fff; text-decoration: none; }

.btn-outline {
  border: 1.5px solid var(--link);
  color: var(--link);
  background: transparent;
}
.btn-outline:hover { background: var(--link); color: #fff; text-decoration: none; }

.btn-ghost {
  color: var(--link);
  padding: 12px 16px;
}
.btn-ghost:hover { text-decoration: underline; }

/* === Product Grid (Homepage) === */
.product-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 24px;
  max-width: var(--max-width);
  margin: 0 auto;
  padding: 0 24px 80px;
}

.product-tile {
  position: relative;
  border-radius: var(--radius);
  overflow: hidden;
  min-height: 540px;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: flex-start;
  padding: 56px 24px 32px;
  text-align: center;
  background-size: cover;
  background-position: center;
  background-repeat: no-repeat;
}

.product-tile::after {
  content: '';
  position: absolute;
  inset: 0;
  background: rgba(0,0,0,0.04);
  z-index: 0;
}

.product-tile.light-text { color: #fff; }
.product-tile.light-text .tile-tagline { color: rgba(255,255,255,0.8); }
.product-tile.light-text::after { background: rgba(0,0,0,0.15); }
.product-tile.light-text .btn-outline { border-color: #fff; color: #fff; }
.product-tile.light-text .btn-outline:hover { background: #fff; color: #1d1d1f; }

.product-tile > * { position: relative; z-index: 1; }

.tile-headline {
  font-size: 40px;
  font-weight: 600;
  letter-spacing: -0.015em;
  line-height: 1.1;
}

.tile-tagline {
  font-size: 19px;
  font-weight: 400;
  color: var(--text-secondary);
  margin-top: 8px;
  line-height: 1.381;
}

.tile-ctas {
  display: flex;
  gap: 16px;
  margin-top: 20px;
  flex-wrap: wrap;
  justify-content: center;
}

.tile-image {
  margin-top: auto;
  max-height: 280px;
  object-fit: contain;
}

@media (max-width: 734px) {
  .product-grid {
    grid-template-columns: 1fr;
    padding: 0 16px 48px;
    gap: 16px;
  }
  .product-tile { min-height: 420px; padding: 40px 20px 24px; }
  .tile-headline { font-size: 32px; }
}

/* === Carousel === */
.carousel-container {
  position: relative;
  max-width: var(--max-width);
  margin: 0 auto;
  padding: 0 24px;
}

.carousel-track-wrapper {
  overflow-x: auto;
  scroll-snap-type: x mandatory;
  -webkit-overflow-scrolling: touch;
  scrollbar-width: none;
  -ms-overflow-style: none;
  padding-bottom: 4px;
}
.carousel-track-wrapper::-webkit-scrollbar { display: none; }

.carousel-track {
  display: flex;
  gap: 20px;
  padding: 0;
}

.carousel-arrow {
  position: absolute;
  top: 50%;
  transform: translateY(-50%);
  z-index: 10;
  width: 48px;
  height: 48px;
  border-radius: 50%;
  background: rgba(255,255,255,0.92);
  box-shadow: var(--shadow);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 18px;
  color: var(--text);
  transition: all 0.2s;
  min-width: 44px;
  min-height: 44px;
}

.carousel-arrow:hover { background: #fff; box-shadow: 0 4px 16px rgba(0,0,0,0.12); }

.carousel-arrow-left { left: 0; }
.carousel-arrow-right { right: 0; }

.carousel-arrow:disabled { opacity: 0.3; cursor: default; }

@media (max-width: 734px) {
  .carousel-arrow { display: none; }
}

/* === Product Card === */
.product-card {
  flex: 0 0 300px;
  scroll-snap-align: start;
  background: #fff;
  border-radius: var(--radius);
  padding: 32px 24px 24px;
  text-align: center;
  transition: transform 0.2s, box-shadow 0.2s;
  position: relative;
  display: flex;
  flex-direction: column;
  align-items: center;
  min-height: 420px;
}

.product-card:hover {
  transform: translateY(-4px);
  box-shadow: var(--shadow);
}

.card-badge {
  position: absolute;
  top: 16px;
  left: 50%;
  transform: translateX(-50%);
  font-size: 11px;
  font-weight: 500;
  color: #bf4800;
  letter-spacing: 0.05em;
}

.card-image {
  width: 160px;
  height: 160px;
  object-fit: contain;
  margin: 20px 0 16px;
}

.card-name {
  font-size: 19px;
  font-weight: 600;
  letter-spacing: 0.012em;
  line-height: 1.21053;
}

.card-tagline {
  font-size: 14px;
  color: var(--text-secondary);
  margin-top: 4px;
  line-height: 1.42859;
}

.card-price {
  font-size: 15px;
  font-weight: 400;
  color: var(--text);
  margin-top: 8px;
}

.card-monthly {
  font-size: 13px;
  color: var(--text-secondary);
  margin-top: 2px;
}

@media (max-width: 734px) {
  .product-card {
    flex: 0 0 260px;
    min-height: 360px;
    padding: 24px 16px 16px;
  }
}

/* === Store Icon Bar === */
.icon-bar {
  display: flex;
  gap: 24px;
  overflow-x: auto;
  padding: 20px 24px 32px;
  max-width: var(--max-width);
  margin: 0 auto;
  scrollbar-width: none;
  -ms-overflow-style: none;
}
.icon-bar::-webkit-scrollbar { display: none; }

.icon-bar-item {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 8px;
  flex: 0 0 auto;
  min-width: 72px;
  text-decoration: none;
  color: var(--text);
  font-size: 13px;
  text-align: center;
}
.icon-bar-item:hover { text-decoration: none; color: var(--link); }

.icon-bar-circle {
  width: 64px;
  height: 64px;
  border-radius: 50%;
  background: var(--bg-alt);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 24px;
  overflow: hidden;
}

/* === Help Cards === */
.help-card {
  flex: 0 0 280px;
  scroll-snap-align: start;
  background: #fff;
  border-radius: var(--radius);
  padding: 32px 24px;
  transition: transform 0.2s, box-shadow 0.2s;
}

.help-card:hover {
  transform: translateY(-4px);
  box-shadow: var(--shadow);
}

.help-card-icon {
  width: 48px;
  height: 48px;
  border-radius: 12px;
  background: var(--bg-alt);
  display: flex;
  align-items: center;
  justify-content: center;
  margin-bottom: 16px;
  font-size: 22px;
}

.help-card-title {
  font-size: 19px;
  font-weight: 600;
  letter-spacing: 0.012em;
  margin-bottom: 8px;
}

.help-card-desc {
  font-size: 14px;
  color: var(--text-secondary);
  line-height: 1.42859;
}

/* === Entertainment Tabs === */
.entertainment-section {
  background: var(--bg-alt);
  padding: 80px 24px;
}

.entertainment-tabs {
  display: flex;
  justify-content: center;
  gap: 8px;
  margin-bottom: 40px;
  flex-wrap: wrap;
}

.tab-btn {
  padding: 10px 22px;
  border-radius: 980px;
  font-size: 15px;
  font-weight: 400;
  background: #fff;
  color: var(--text);
  transition: all 0.2s;
  border: 1px solid var(--border);
}

.tab-btn.active,
.tab-btn:hover {
  background: var(--text);
  color: #fff;
  border-color: var(--text);
}

.tab-panel { display: none; }
.tab-panel.active { display: block; }

.tab-content-cards {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(240px, 1fr));
  gap: 20px;
  max-width: var(--max-width);
  margin: 0 auto;
}

.tab-card {
  background: #fff;
  border-radius: var(--radius-sm);
  overflow: hidden;
  transition: transform 0.2s, box-shadow 0.2s;
}

.tab-card:hover {
  transform: translateY(-4px);
  box-shadow: var(--shadow);
}

.tab-card-img {
  width: 100%;
  aspect-ratio: 16/10;
  background: linear-gradient(135deg, #e8e8ed, #d2d2d7);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 14px;
  color: var(--text-secondary);
}

.tab-card-body {
  padding: 16px 20px 20px;
}

.tab-card-title {
  font-size: 15px;
  font-weight: 600;
  margin-bottom: 6px;
}

.tab-card-desc {
  font-size: 13px;
  color: var(--text-secondary);
  margin-bottom: 10px;
}

.tab-card-link {
  font-size: 14px;
  color: var(--link);
}

/* === Sticky Section Nav (Category Pages) === */
.section-nav {
  position: sticky;
  top: 52px;
  z-index: 999;
  background: rgba(255,255,255,0.92);
  backdrop-filter: saturate(180%) blur(20px);
  -webkit-backdrop-filter: saturate(180%) blur(20px);
  border-bottom: 1px solid rgba(0,0,0,0.08);
}

.section-nav-inner {
  max-width: var(--max-width);
  margin: 0 auto;
  display: flex;
  align-items: center;
  gap: 4px;
  padding: 0 24px;
  overflow-x: auto;
  scrollbar-width: none;
  -ms-overflow-style: none;
  white-space: nowrap;
}

.section-nav-inner::-webkit-scrollbar { display: none; }

.section-nav-link {
  display: inline-flex;
  align-items: center;
  padding: 12px 18px;
  font-size: 13px;
  font-weight: 400;
  color: var(--text);
  text-decoration: none;
  border-bottom: 2px solid transparent;
  transition: all 0.2s;
  white-space: nowrap;
}
.section-nav-link:hover,
.section-nav-link.active {
  color: var(--link);
  border-bottom-color: var(--link);
  text-decoration: none;
}

/* === Category Hero === */
.category-hero {
  text-align: center;
  padding: 60px 24px 48px;
}

.category-hero h1 {
  font-size: 48px;
  font-weight: 600;
  letter-spacing: -0.015em;
  margin-bottom: 8px;
}

.category-hero p {
  font-size: 19px;
  color: var(--text-secondary);
}

/* === Brand Collab === */
.brand-collab {
  background: linear-gradient(135deg, #1a1a2e, #16213e);
  color: #fff;
  text-align: center;
  padding: 80px 24px;
  border-radius: var(--radius);
  max-width: var(--max-width);
  margin: 0 auto 80px;
}

.brand-collab h2 {
  font-size: 40px;
  font-weight: 600;
  letter-spacing: -0.015em;
  margin-bottom: 12px;
}

.brand-collab p {
  font-size: 19px;
  color: rgba(255,255,255,0.8);
  margin-bottom: 24px;
}

.brand-collab .btn-outline {
  border-color: #fff;
  color: #fff;
}
.brand-collab .btn-outline:hover { background: #fff; color: #1a1a2e; }

/* === Featured Cards (Savings, etc.) === */
.feature-card {
  flex: 0 0 280px;
  scroll-snap-align: start;
  background: #fff;
  border-radius: var(--radius);
  padding: 32px 24px;
  text-align: center;
  transition: transform 0.2s, box-shadow 0.2s;
}

.feature-card:hover {
  transform: translateY(-4px);
  box-shadow: var(--shadow);
}

.feature-card-icon {
  width: 56px;
  height: 56px;
  border-radius: 50%;
  background: var(--bg-alt);
  display: flex;
  align-items: center;
  justify-content: center;
  margin: 0 auto 16px;
  font-size: 24px;
}

.feature-card-title {
  font-size: 17px;
  font-weight: 600;
  margin-bottom: 8px;
}

.feature-card-desc {
  font-size: 14px;
  color: var(--text-secondary);
  line-height: 1.42859;
}

/* === Quick Links === */
.quick-links {
  display: flex;
  justify-content: center;
  gap: 12px;
  flex-wrap: wrap;
  max-width: var(--max-width);
  margin: 0 auto;
  padding: 60px 24px;
}

.quick-link-btn {
  padding: 12px 24px;
  border-radius: 980px;
  font-size: 15px;
  font-weight: 400;
  background: var(--bg-alt);
  color: var(--text);
  text-decoration: none;
  transition: all 0.2s;
}
.quick-link-btn:hover {
  background: #e8e8ed;
  text-decoration: none;
  color: var(--text);
}

/* === Setup Support === */
.setup-support {
  max-width: var(--max-width);
  margin: 0 auto;
  padding: 0 24px 80px;
}

.setup-card {
  display: flex;
  align-items: center;
  gap: 40px;
  background: var(--bg-alt);
  border-radius: var(--radius);
  padding: 56px 48px;
}
.setup-card.reverse { flex-direction: row-reverse; }

.setup-card-content { flex: 1; }
.setup-card-content h3 {
  font-size: 32px;
  font-weight: 600;
  letter-spacing: -0.01em;
  margin-bottom: 12px;
}
.setup-card-content p {
  font-size: 17px;
  color: var(--text-secondary);
  margin-bottom: 20px;
}

.setup-card-img {
  flex: 0 0 200px;
  height: 200px;
  background: #d2d2d7;
  border-radius: var(--radius-sm);
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--text-secondary);
  font-size: 14px;
}

@media (max-width: 734px) {
  .setup-card, .setup-card.reverse { flex-direction: column; text-align: center; }
  .setup-card { padding: 32px 24px; }
}

/* === Special Stores === */
.special-stores {
  max-width: var(--max-width);
  margin: 0 auto;
  padding: 0 24px 80px;
}

.special-stores-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 20px;
}

.special-store-card {
  background: var(--bg-alt);
  border-radius: var(--radius);
  padding: 40px 32px;
  text-align: center;
  transition: transform 0.2s;
}
.special-store-card:hover { transform: translateY(-4px); }

.special-store-card h4 {
  font-size: 21px;
  font-weight: 600;
  margin-bottom: 8px;
}

.special-store-card p {
  font-size: 14px;
  color: var(--text-secondary);
  margin-bottom: 16px;
}

@media (max-width: 734px) {
  .special-stores-grid { grid-template-columns: 1fr; }
}

/* === Footer === */
.footer {
  background: var(--bg-alt);
  padding: 40px 24px 24px;
  font-size: 12px;
  color: var(--text-secondary);
}

.footer-grid {
  max-width: var(--max-width);
  margin: 0 auto;
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(160px, 1fr));
  gap: 32px;
  padding-bottom: 32px;
  border-bottom: 1px solid var(--border);
}

.footer-col h4 {
  font-size: 13px;
  font-weight: 600;
  color: var(--text);
  margin-bottom: 10px;
  letter-spacing: -0.01em;
}

.footer-col ul { list-style: none; }

.footer-col ul li { margin-bottom: 6px; }

.footer-col ul li a {
  font-size: 12px;
  color: var(--text-secondary);
}
.footer-col ul li a:hover { color: var(--text); text-decoration: underline; }

.footer-bottom {
  max-width: var(--max-width);
  margin: 0 auto;
  padding-top: 24px;
  line-height: 1.42859;
}

.footer-bottom p { margin-bottom: 8px; }
.footer-bottom a { color: var(--text-secondary); text-decoration: underline; }
.footer-bottom a:hover { color: var(--text); }

/* Mobile footer accordion */
.footer-col-toggle {
  display: none;
  width: 100%;
  text-align: left;
  font-size: 13px;
  font-weight: 600;
  color: var(--text);
  padding: 10px 0;
  justify-content: space-between;
  align-items: center;
  border-bottom: 1px solid var(--border);
  background: none;
}

.footer-col-toggle::after {
  content: '+';
  font-size: 18px;
  font-weight: 300;
}

.footer-col-toggle.open::after {
  content: '−';
}

@media (max-width: 734px) {
  .footer-grid {
    display: flex;
    flex-direction: column;
    gap: 0;
  }

  .footer-col h4 { display: none; }

  .footer-col-toggle { display: flex; }

  .footer-col ul {
    max-height: 0;
    overflow: hidden;
    transition: max-height 0.3s ease;
    padding: 0 0 0 8px;
  }

  .footer-col.open ul {
    max-height: 600px;
    padding-bottom: 12px;
  }
}

/* === Store Difference / Product Experience === */
.experience-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(280px, 1fr));
  gap: 20px;
  max-width: var(--max-width);
  margin: 0 auto;
  padding: 0 24px 80px;
}

/* === Promo banner === */
.promo-banner {
  max-width: var(--max-width);
  margin: 0 auto 48px;
  padding: 0 24px;
  text-align: center;
