  content: '+';
  font-size: 18px;
  font-weight: 300;
}

.footer-col-toggle.open::after {
  content: '−';
}

@media (max-width: 734px) {
  .footer-grid {
    display: flex;
    flex-direction: column;
    gap: 0;
  }

  .footer-col h4 { display: none; }

  .footer-col-toggle { display: flex; }

  .footer-col ul {
    max-height: 0;
    overflow: hidden;
    transition: max-height 0.3s ease;
    padding: 0 0 0 8px;
  }

  .footer-col.open ul {
    max-height: 600px;
    padding-bottom: 12px;
  }
}

/* === Store Difference / Product Experience === */
.experience-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(280px, 1fr));
  gap: 20px;
  max-width: var(--max-width);
  margin: 0 auto;
  padding: 0 24px 80px;
}

/* === Promo banner === */
.promo-banner {
  max-width: var(--max-width);
  margin: 0 auto 48px;
  padding: 0 24px;
  text-align: center;
  font-size: 14px;
  color: var(--text-secondary);
}

/* === Product experience split section === */
.experience-split {
  max-width: var(--max-width);
  margin: 0 auto;
  padding: 0 24px 80px;
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 24px;
}

.exp-split-card {
  background: var(--bg-alt);
  border-radius: var(--radius);
  padding: 48px 40px;
  text-align: center;
}

@media (max-width: 734px) {
  .experience-split { grid-template-columns: 1fr; }
}

/* === Utility === */
.text-center { text-align: center; }
.mt-0 { margin-top: 0; }
.mb-0 { margin-bottom: 0; }

/* Icons placeholder */
.icon {
  width: 36px;
  height: 36px;
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--text-secondary);
}
