.help-card-title {
  font-size: 19px;
  font-weight: 600;
  letter-spacing: 0.012em;
  margin-bottom: 8px;
}

.help-card-desc {
  font-size: 14px;
  color: var(--text-secondary);
  line-height: 1.42859;
}

/* === Entertainment Tabs === */
.entertainment-section {
  background: var(--bg-alt);
  padding: 80px 24px;
}

.entertainment-tabs {
  display: flex;
  justify-content: center;
  gap: 8px;
  margin-bottom: 40px;
  flex-wrap: wrap;
}

.tab-btn {
  padding: 10px 22px;
  border-radius: 980px;
  font-size: 15px;
  font-weight: 400;
  background: #fff;
  color: var(--text);
  transition: all 0.2s;
  border: 1px solid var(--border);
}

.tab-btn.active,
.tab-btn:hover {
  background: var(--text);
  color: #fff;
  border-color: var(--text);
}

.tab-panel { display: none; }
.tab-panel.active { display: block; }

.tab-content-cards {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(240px, 1fr));
  gap: 20px;
  max-width: var(--max-width);
  margin: 0 auto;
}

.tab-card {
  background: #fff;
  border-radius: var(--radius-sm);
  overflow: hidden;
  transition: transform 0.2s, box-shadow 0.2s;
}

.tab-card:hover {
  transform: translateY(-4px);
  box-shadow: var(--shadow);
}

.tab-card-img {
  width: 100%;
  aspect-ratio: 16/10;
  background: linear-gradient(135deg, #e8e8ed, #d2d2d7);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 14px;
  color: var(--text-secondary);
}

.tab-card-body {
  padding: 16px 20px 20px;
}

.tab-card-title {
  font-size: 15px;
  font-weight: 600;
  margin-bottom: 6px;
}

.tab-card-desc {
  font-size: 13px;
  color: var(--text-secondary);
  margin-bottom: 10px;
}

.tab-card-link {
  font-size: 14px;
  color: var(--link);
}

/* === Sticky Section Nav (Category Pages) === */
.section-nav {
  position: sticky;
  top: 52px;
  z-index: 999;
  background: rgba(255,255,255,0.92);
  backdrop-filter: saturate(180%) blur(20px);
  -webkit-backdrop-filter: saturate(180%) blur(20px);
  border-bottom: 1px solid rgba(0,0,0,0.08);
}

.section-nav-inner {
  max-width: var(--max-width);
  margin: 0 auto;
  display: flex;
  align-items: center;
  gap: 4px;
  padding: 0 24px;
  overflow-x: auto;
  scrollbar-width: none;
  -ms-overflow-style: none;
  white-space: nowrap;
}

.section-nav-inner::-webkit-scrollbar { display: none; }

.section-nav-link {
  display: inline-flex;
  align-items: center;
  padding: 12px 18px;
  font-size: 13px;
  font-weight: 400;
  color: var(--text);
  text-decoration: none;
  border-bottom: 2px solid transparent;
  transition: all 0.2s;
  white-space: nowrap;
}
.section-nav-link:hover,
.section-nav-link.active {
  color: var(--link);
  border-bottom-color: var(--link);
  text-decoration: none;
