/* === Category Hero === */
.category-hero {
  text-align: center;
  padding: 60px 24px 48px;
}

.category-hero h1 {
  font-size: 48px;
  font-weight: 600;
  letter-spacing: -0.015em;
  margin-bottom: 8px;
}

.category-hero p {
  font-size: 19px;
  color: var(--text-secondary);
}

/* === Brand Collab === */
.brand-collab {
  background: linear-gradient(135deg, #1a1a2e, #16213e);
  color: #fff;
  text-align: center;
  padding: 80px 24px;
  border-radius: var(--radius);
  max-width: var(--max-width);
  margin: 0 auto 80px;
}

.brand-collab h2 {
  font-size: 40px;
  font-weight: 600;
  letter-spacing: -0.015em;
  margin-bottom: 12px;
}

.brand-collab p {
  font-size: 19px;
  color: rgba(255,255,255,0.8);
  margin-bottom: 24px;
}

.brand-collab .btn-outline {
  border-color: #fff;
  color: #fff;
}
.brand-collab .btn-outline:hover { background: #fff; color: #1a1a2e; }

/* === Featured Cards (Savings, etc.) === */
.feature-card {
  flex: 0 0 280px;
  scroll-snap-align: start;
  background: #fff;
  border-radius: var(--radius);
  padding: 32px 24px;
  text-align: center;
  transition: transform 0.2s, box-shadow 0.2s;
}

.feature-card:hover {
  transform: translateY(-4px);
  box-shadow: var(--shadow);
}

.feature-card-icon {
  width: 56px;
  height: 56px;
  border-radius: 50%;
  background: var(--bg-alt);
  display: flex;
  align-items: center;
  justify-content: center;
  margin: 0 auto 16px;
  font-size: 24px;
}

.feature-card-title {
  font-size: 17px;
  font-weight: 600;
  margin-bottom: 8px;
}

.feature-card-desc {
  font-size: 14px;
  color: var(--text-secondary);
  line-height: 1.42859;
}

/* === Quick Links === */
.quick-links {
  display: flex;
  justify-content: center;
  gap: 12px;
  flex-wrap: wrap;
  max-width: var(--max-width);
