    display: flex;
    flex-direction: column;
    gap: 0;
  }

  .footer-col h4 { display: none; }

  .footer-col-toggle { display: flex; }

  .footer-col ul {
    max-height: 0;
    overflow: hidden;
    transition: max-height 0.3s ease;
    padding: 0 0 0 8px;
  }

  .footer-col.open ul {
    max-height: 600px;
    padding-bottom: 12px;
  }
}

