.experience-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(280px, 1fr));
  gap: 20px;
  max-width: var(--max-width);
  margin: 0 auto;
  padding: 0 24px 80px;
}

/* === Promo banner === */
.promo-banner {
  max-width: var(--max-width);
  margin: 0 auto 48px;
  padding: 0 24px;
  text-align: center;
  font-size: 14px;
  color: var(--text-secondary);
}

/* === Product experience split section === */
.experience-split {
  max-width: var(--max-width);
  margin: 0 auto;
  padding: 0 24px 80px;
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 24px;
}

.exp-split-card {
  background: var(--bg-alt);
  border-radius: var(--radius);
  padding: 48px 40px;
  text-align: center;
}

@media (max-width: 734px) {
