*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

:root {
  --bg: #ffffff;
  --bg-alt: #f5f5f7;
  --text: #1d1d1f;
  --text-secondary: #5c5c62;
  --link: #0066cc;
  --link-hover: #004499;
  --border: #d2d2d7;
  --shadow: 0 2px 12px rgba(0,0,0,0.08);
  --radius: 18px;
  --radius-sm: 12px;
  --radius-pill: 980px;
  --nav-height: 52px;
  --max-width: 1200px;
  --card-image-bg: linear-gradient(135deg, #e8e8ed, #d2d2d7);
  --card-image-bg-dark: linear-gradient(135deg, #1d1d1f, #3a3a3f);
  --font-stack: -apple-system, BlinkMacSystemFont, 'SF Pro Display', 'SF Pro Text', 'Helvetica Neue', Arial, sans-serif;
}

html { scroll-behavior: smooth; }

body {
  font-family: var(--font-stack);
  color: var(--text);
  background: var(--bg);
  line-height: 1.47059;
  font-weight: 400;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

a { color: var(--link); text-decoration: none; }

